expected_enum(typ, label) as (values ('app_role','mentee'),('app_role','mentor'),('app_role','supervisor'),('app_role','program_manager'),('app_role','admin'),('app_role','support'),('assessment_status','draft'),('assessment_status','submitted'),('assessment_status','needs_info'),('assessment_status','reviewed'),('goal_status','not_started'),('goal_status','in_progress'),('goal_status','achieved'),('goal_status','partially_achieved'),('goal_status','not_achieved'),('goal_status','dropped'),('mentor_status','draft'),('mentor_status','pending'),('mentor_status','approved'),('mentor_status','rejected'),('mentor_status','suspended'),('mentorship_status','pending_setup'),('mentorship_status','active'),('mentorship_status','paused'),('mentorship_status','completed'),('mentorship_status','cancelled'),('note_visibility','private'),('note_visibility','staff'),('note_visibility','mentee'),('payment_status','pending'),('payment_status','paid'),('payment_status','failed'),('payment_status','refunded'),('payment_status','cancelled'),('plan_status','draft'),('plan_status','pending_approval'),('plan_status','active'),('plan_status','on_hold'),('plan_status','completed'),('plan_status','cancelled'),('request_status','submitted'),('request_status','under_review'),('request_status','accepted'),('request_status','rejected'),('request_status','cancelled'),('session_status','scheduled'),('session_status','confirmed'),('session_status','completed'),('session_status','cancelled'),('session_status','no_show'),('session_status','failed'),('task_kind','exercise'),('task_kind','project'),('task_kind','review'),('task_kind','session'),('task_kind','resource'),('task_status','not_started'),('task_status','in_progress'),('task_status','submitted'),('task_status','changes_requested'),('task_status','completed'),('task_status','cancelled')),
missing_cols as (
  select e.t, e.c from expected_cols e
  left join information_schema.columns ic on ic.table_schema = 'public' and ic.table_name = e.t and ic.column_name = e.c
  where ic.column_name is null),
missing_enum as (
  select x.typ, x.label from expected_enum x
  where not exists (select 1 from pg_enum pe join pg_type pt on pt.oid = pe.enumtypid join pg_namespace pn on pn.oid = pt.typnamespace
                    where pn.nspname = 'public' and pt.typname = x.typ and pe.enumlabel = x.label)),
checks(item, ok, detail) as (
  select 'all tables & columns', not exists (select 1 from missing_cols),
         (select string_agg(t || '.' || c, ', ') from missing_cols)
  union all
  select 'all enum values', not exists (select 1 from missing_enum),
         (select string_agg(typ || ':' || label, ', ') from missing_enum)
  union all
  select 'views (3)', (select count(*) from information_schema.views where table_schema = 'public' and table_name in ('mentor_directory','mentor_admin_view','public_reviews')) = 3, null
  union all
  select 'RLS on all tables', not exists (select 1 from pg_tables where schemaname = 'public' and not rowsecurity),
         (select string_agg(tablename, ', ') from pg_tables where schemaname = 'public' and not rowsecurity)
  union all
  select 'RPC functions (8)', (select count(*) from pg_proc where pronamespace = 'public'::regnamespace and proname in (
     'decide_request','set_plan_status','set_task_status','admin_set_role','admin_decide_mentor','admin_set_order_status','set_mentor_tags','apply_as_mentor')) = 8, null
  union all
  select 'signup trigger', exists (select 1 from pg_trigger where tgname = 'on_auth_user_created'), null
  union all
  select 'seed: categories', (select count(*) from public.categories) >= 8, 'run supabase/seed.sql'
  union all
  select 'seed: assessment questions', (select count(*) from public.assessment_questions) >= 9, 'run supabase/seed.sql'
  union all
  select 'seed: settings', (select count(*) from public.system_settings) >= 6, 'run supabase/seed.sql'
  union all
  select 'realtime: messages', exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'messages'), null
  union all
  select 'at least one admin', exists (select 1 from public.user_roles where role = 'admin'), 'run supabase/make_admin.sql'
)
select case when ok then '✅' else '❌' end as status, item, case when ok then null else detail end as missing from checks;
